/* cppi::410377b061679919fbb966955b6e941121d1984e2eb082a236a9a462f5148551 */
with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from ( select distinct(business_date), id_cppibsec from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2 )
    ) select * from cslDates

